def stage_public_projection(record):
    values = dict(record.get('values', {}))
    public = sorted({str(name) for name in record.get('public_fields', [])})
    selected = {key: values[key] for key in public if key in values}
    return {'selected': selected}

def finalize_public_projection(staged):
    return {'decision': 'allowed', 'fields': dict(staged.get('selected', {}))}
